"""Lead capture: validates a form submission before it is stored."""
import re

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
PHONE_RE = re.compile(r"^[0-9 +()-]{7,20}$")


class InvalidSubmission(ValueError):
    pass


def submit_lead(form):
    """Return the cleaned lead, or raise InvalidSubmission. `form` has name, email, phone and page_id."""
    if not EMAIL_RE.match(form.get("email", "")):
        raise InvalidSubmission("email")
    if not PHONE_RE.match(form.get("phone", "")):
        raise InvalidSubmission("phone")
    return {"name": form["name"].strip(), "email": form["email"].lower(), "phone": form["phone"],
            "page_id": form.get("page_id")}
